contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable {
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            c.owner() == ownerBefore &&
            c.depositsCount() == depositsBefore
        );
    }

    receive() external payable {}
}

